n=30
grid=[[0]*n for _ in range(n)]
starts=[1,8,15,22,29]
# The visible 4x4 array of solid interiors.
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
for ti,r0 in enumerate(starts):
 for tj,c0 in enumerate(starts):
  for dr in range(5):
   for dc in range(5):
    r,c=r0+dr,c0+dc
    if r<n and c<n:
     grid[r][c]=4 if dr in (0,4) or dc in (0,4) else colors[ti][tj]
# Draw same-color bridges only in the two-cell gaps, matching the marker's 3-cell thickness.
def hbridge(tile_row, cstart, cend, color):
 r0=starts[tile_row]
 for tj in range(cstart,cend):
  gap_col=starts[tj]+5
  for r in range(r0+1,r0+4):
   for c in (gap_col,gap_col+1):
    if r<n and c<n: grid[r][c]=color
def vbridge(tile_col, rstart, rend, color):
 c0=starts[tile_col]
 for ti in range(rstart,rend):
  gap_row=starts[ti]+5
  for r in (gap_row,gap_row+1):
   for c in range(c0+1,c0+4):
    if r<n and c<n: grid[r][c]=color
# Color 3 at rows 0,2 and columns 0,3.
for tr in (0,2): hbridge(tr,0,3,3)
for tc in (0,3): vbridge(tc,0,2,3)
# Color 8 at rows 1,3 and columns 1,2.
for tr in (1,3): hbridge(tr,1,2,8)
for tc in (1,2): vbridge(tc,1,3,8)
print('\n'.join(' '.join(map(str,row)) for row in grid))
